// ☰ → Extensions: the browser extensions that bring web pages into Recall,
// each downloadable as a ready-to-load .zip.
//
// There is no build step and nothing prebuilt in the repository: the deploy
// publishes the extension folders as they are, so a download fetches each
// file the catalog lists (src/extensions/catalog.js, generated by
// tools/extension-catalog.mjs) and zips them right here with the app's own zip
// writer. Every entry sits under one top-level folder, so unzipping gives a
// folder that Chrome's "Load unpacked" takes as it is.

import { EXTENSIONS } from "./catalog.js?v=__BUILD__";
import { LiteZip } from "../backup/zip-lite.js?v=__BUILD__";
import { downloadBlob } from "../backup/backup.js?v=__BUILD__";
import { showToast } from "../ui/feedback.js?v=__BUILD__";
import { lockPageScroll, unlockPageScroll } from "../ui/overlays.js?v=__BUILD__";

export const extensionsBtn = document.getElementById("extensionsBtn");
export const extensionsModal = document.getElementById("extensionsModal");
const extensionsCloseBtn = document.getElementById("extensionsCloseBtn");
const extensionsList = document.getElementById("extensionsList");

const extensionJobs = new Set();

export function formatSize(bytes) {
  if (bytes >= 1048576) return `${(bytes / 1048576).toFixed(1)} MB`;
  return `${Math.max(1, Math.round(bytes / 1024))} KB`;
}

function extEl(tag, className, text) {
  const el = document.createElement(tag);
  if (className) el.className = className;
  if (text != null) el.textContent = text;
  return el;
}

function extensionCard(ext) {
  const item = extEl("article", "ext-card");
  item.dataset.extension = ext.id;

  const head = extEl("div", "ext-card-head");
  const icon = extEl("img", "ext-card-icon");
  icon.src = `${ext.folder}/icons/icon-48.png`;
  icon.alt = "";
  icon.width = 40;
  icon.height = 40;
  const titles = extEl("div", "ext-card-titles");
  titles.append(extEl("h3", "ext-card-name", ext.name), extEl("span", "ext-card-meta", `Version ${ext.version} · ${formatSize(ext.bytes)}`));
  head.append(icon, titles);

  const tagline = extEl("p", "ext-card-tagline", ext.tagline);
  const details = extEl("ul", "ext-card-details");
  ext.details.forEach((line) => details.append(extEl("li", null, line)));
  const facts = extEl("dl", "ext-card-facts");
  facts.append(extEl("dt", null, "Shortcut"), extEl("dd", null, ext.shortcut), extEl("dt", null, "Access"), extEl("dd", null, ext.permissions));

  const button = extEl("button", "sync-modal-btn is-primary ext-card-download", "Download .zip");
  button.type = "button";
  button.dataset.extension = ext.id;
  button.addEventListener("click", () => downloadExtension(ext, button));

  item.append(head, tagline, details, facts, button);
  return item;
}

function paintExtensionStore() {
  if (!extensionsList || extensionsList.childElementCount) return;
  EXTENSIONS.forEach((ext) => extensionsList.append(extensionCard(ext)));
}

// The zip, as bytes in a Blob. Exported for the checks.
export async function buildExtensionZip(ext, onProgress = () => {}) {
  const bytes = new Array(ext.files.length);
  let next = 0;
  let done = 0;
  // A few at a time: the Clipper alone is forty-odd files.
  const worker = async () => {
    while (next < ext.files.length) {
      const index = next;
      next += 1;
      const file = ext.files[index];
      const res = await fetch(`${ext.folder}/${file.path}`, { cache: "no-cache" });
      if (!res.ok) throw new Error(`${file.path}: ${res.status}`);
      bytes[index] = new Uint8Array(await res.arrayBuffer());
      done += 1;
      onProgress(done, ext.files.length);
    }
  };
  await Promise.all(Array.from({ length: 6 }, worker));
  // Members in the catalog's order, whatever order the fetches finished in.
  // Pictures and fonts are compressed already; deflating them again only costs time.
  const zip = new LiteZip();
  ext.files.forEach((file, i) => {
    zip.file(`${ext.folder}/${file.path}`, bytes[i], { compression: /\.(png|woff2?)$/i.test(file.path) ? "STORE" : "DEFLATE" });
  });
  return zip.generateAsync({ type: "blob" });
}

async function downloadExtension(ext, button) {
  if (extensionJobs.has(ext.id)) return;
  extensionJobs.add(ext.id);
  const label = button.textContent;
  button.disabled = true;
  try {
    const blob = await buildExtensionZip(ext, (done, total) => {
      button.textContent = `Packing ${done} of ${total}…`;
    });
    downloadBlob(blob, `${ext.folder}-${ext.version}.zip`);
    showToast(`${ext.name} downloaded — unzip it, then Load unpacked`, "success");
  } catch (error) {
    console.warn("Extension download failed", error);
    showToast(navigator.onLine === false
      ? "Connect to the internet once to download extensions"
      : `Could not download ${ext.name}`, "error");
  } finally {
    extensionJobs.delete(ext.id);
    button.disabled = false;
    button.textContent = label;
  }
}

export function openExtensionStore() {
  if (!extensionsModal) return;
  paintExtensionStore();
  if (extensionsModal.hidden) {
    extensionsModal.hidden = false;
    lockPageScroll();
  }
}

export function closeExtensionStore() {
  if (!extensionsModal || extensionsModal.hidden) return;
  extensionsModal.hidden = true;
  unlockPageScroll();
}

export function initExtensionStore() {
  extensionsBtn?.addEventListener("click", openExtensionStore);
  extensionsCloseBtn?.addEventListener("click", closeExtensionStore);
  extensionsModal?.addEventListener("click", (event) => {
    if (event.target === extensionsModal) closeExtensionStore();
  });
  extensionsModal?.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.stopPropagation();
      closeExtensionStore();
    }
  });
}
